contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        if (amount > balBefore) { amount = balBefore; }
        balBefore = address(c).balance;
        c.withdraw(amount); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBefore - amount);
    }
    receive() external payable {}
    fallback() external payable {}
}

