// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.depositsCount() {} catch { return; }
        uint balBefore = address(c).balance;
        if (amount > balBefore) { amount = balBefore; }
        balBefore = address(c).balance;
        try c.withdraw(amount) {} catch { return; }
        assertTrue(address(c).balance == balBefore - amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}

    fallback() external payable {}
}
